sys_script.script:
/**
 * 20-Block booking on non-business days
 *
 * Aborts the insert/update when the reservation start date falls on a Calendar
 * Day flagged as a Holiday, or when no Business Day Calendar Day record exists
 * for that date.
 */
(function executeRule(/** @type {any} */ current, /** @type {any} */ previous) {
    if (!current.start_date.changes()) {
        return;
    }

    var startDate = current.getValue('start_date');
    if (!startDate) {
        return;
    }

    var isHoliday = false;
    var isBusinessDay = false;

    var calDay = new GlideRecord('x_2203703_car_re_0_cal_day');
    calDay.addQuery('date', startDate);
    calDay.query();
    while (calDay.next()) {
        var dayType = calDay.getValue('day_type');
        if (dayType === 'holiday') {
            isHoliday = true;
        } else if (dayType === 'business_day') {
            isBusinessDay = true;
        }
    }

    if (isHoliday) {
        gs.addErrorMessage(
            'Bookings are not allowed on ' + startDate + ' because it is marked as a holiday.'
        );
        current.setAbortAction(true);
        return;
    }

    if (!isBusinessDay) {
        gs.addErrorMessage(
            'Bookings are only allowed on business days. ' +
                startDate +
                ' is not registered as a business day on the rental calendar.'
        );
        current.setAbortAction(true);
    }
})(current, previous);
